import{_ as a,o,c as t,a0 as s}from"./chunks/framework.BQGW-Zpy.js";const p=JSON.parse('{"title":"Database: MongoDB + Prisma ORM","description":"","frontmatter":{},"headers":[],"relativePath":"reference/mongodb-setup.md","filePath":"reference/mongodb-setup.md"}'),n={name:"reference/mongodb-setup.md"};function r(i,e,d,c,l,h){return o(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="database-mongodb-prisma-orm" tabindex="-1">Database: MongoDB + Prisma ORM <a class="header-anchor" href="#database-mongodb-prisma-orm" aria-label="Permalink to &quot;Database: MongoDB + Prisma ORM&quot;">​</a></h1><p>Business records (transfers, compliance records, community posts) are stored in MongoDB, accessed through Prisma ORM. Only a hash and pseudonymous metadata are ever anchored on Hedera; the records themselves live here.</p><h2 id="version-requirement" tabindex="-1">Version requirement <a class="header-anchor" href="#version-requirement" aria-label="Permalink to &quot;Version requirement&quot;">​</a></h2><p><code>package.json</code> pins <code>&quot;prisma&quot;: &quot;^6.19.3&quot;</code> and <code>&quot;@prisma/client&quot;: &quot;^6.19.3&quot;</code>. Prisma 7 does not yet support MongoDB as a provider, so this project stays on the 6.x line until that changes.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><ol><li>Set <code>MONGO_URI</code> in your <code>.env</code> file. The connection string must include a database name (e.g. <code>mongodb+srv://user:pass@cluster.mongodb.net/crossborder?appName=...</code>, the <code>crossborder</code> segment is the database name and cannot be left blank).</li><li>Generate the Prisma client:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db:generate</span></span></code></pre></div>This requires internet access to <code>binaries.prisma.sh</code> to download Prisma&#39;s query engine.</li><li>On Render: add <code>npm run db:generate</code> to the build command (Settings → Build Command), e.g. <code>npm install &amp;&amp; npm run db:generate</code>. Add <code>MONGO_URI</code> under Environment Variables, not committed to git.</li></ol><h2 id="fallback-behavior" tabindex="-1">Fallback behavior <a class="header-anchor" href="#fallback-behavior" aria-label="Permalink to &quot;Fallback behavior&quot;">​</a></h2><p>If <code>MONGO_URI</code> isn&#39;t set, the Prisma client hasn&#39;t been generated, or a database operation fails at runtime, <code>backend/db/store.mjs</code> logs a warning and falls back to a local JSON file (<code>backend/db.json</code>) automatically rather than crashing. A misconfigured or temporarily unreachable database degrades gracefully instead of taking the API down.</p><h2 id="security-note" tabindex="-1">Security note <a class="header-anchor" href="#security-note" aria-label="Permalink to &quot;Security note&quot;">​</a></h2><p>A MongoDB connection string is a live credential. If one is ever exposed (shared in a chat, an issue tracker, or committed by mistake), rotate that database user&#39;s password in MongoDB Atlas.</p>',10)])])}const u=a(n,[["render",r]]);export{p as __pageData,u as default};
